{#- Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/feature-grid.json
    A section with a heading and the features as a grid of cards or tiles, or as rows with a picture. Icons are Lucide names. Axes: layout (grid, rows), columns, item (card, tile, cell: bordered tile with a round icon), media side (rows), density, tone.
    Props (p): id, title, features, action, layout, cols, item, mediaSide, tone, density, landmarkLabel. -#}
{%- set v_id = (p.id ?? null) -%}
{%- set v_title = (p.title ?? null) -%}
{%- set v_features = (p.features ?? null) -%}
{%- set v_action = (p.action ?? null) -%}
{%- set v_layout = (p.layout ?? 'grid') -%}
{%- set v_cols = (p.cols ?? '1-3') -%}
{%- set v_item = (p.item ?? 'card') -%}
{%- set v_mediaSide = (p.mediaSide ?? 'end') -%}
{%- set v_tone = (p.tone ?? 'default') -%}
{%- set v_density = (p.density ?? 'default') -%}
{%- set v_landmarkLabel = (p.landmarkLabel ?? null) -%}
{%- if ui_t(ui_eq(v_item, 'cell')) %}
  {%- set c_4 -%}
    {%- set c_3 -%}
      {%- set c_1 -%}
        {{ ui_text(v_title) }}
      {%- endset -%}
      {{ include('ui/title/title.html.twig', {'p': {'As': ui_i(2), 'Size': 'sm', 'Weight': 'semibold', 'Class': 'leading-7', 'Attrs': ui_attrs(['id', ui_add(v_id, '-title')])}, 'children': c_1}, with_context = false) }}
      {%- if ui_t(ui_get(v_action, ['label'])) %}
        {%- set c_2 -%}
          {{ ui_text(ui_get(v_action, ['label'])) }}
        {%- endset -%}
        {{ include('ui/link/link.html.twig', {'p': {'Href': ui_s(ui_coalesce([ui_get(v_action, ['href']), '#/'])), 'Variant': 'default', 'Class': ui_s(ui_cnv([ui_preset('blocks/presets/defaults.json', ['text', 'tiny']), 'shrink-0 font-medium leading-5'])), 'Attrs': ui_attrs(['data-testid', 'section-action'])}, 'children': c_2}, with_context = false) }}
      {%- endif %}
    {%- endset -%}
    {{ include('ui/group/group.html.twig', {'p': {'Gap': '4', 'Align': 'center', 'Justify': 'between', 'Class': 'w-full'}, 'children': c_3}, with_context = false) }}
    {{ include('blocks/feature-cards.html.twig', {'p': {'features': v_features, 'cols': v_cols, 'item': v_item}}, with_context = false) }}
  {%- endset -%}
  {{ include('blocks/section-frame.html.twig', {'p': {'id': v_id, 'tone': v_tone, 'density': v_density, 'measure': 'fill', 'className': ui_cnv(['py-0']), 'landmarkLabel': v_landmarkLabel}, 'children': c_4}, with_context = false) }}
{%- else %}
  {%- set c_5 -%}
    {%- if ui_t(ui_eq(v_layout, 'rows')) %}
      {{ include('blocks/feature-rows.html.twig', {'p': {'features': v_features, 'mediaSide': v_mediaSide}}, with_context = false) }}
    {%- else %}
      {{ include('blocks/feature-cards.html.twig', {'p': {'features': v_features, 'cols': v_cols, 'item': v_item}}, with_context = false) }}
    {%- endif %}
  {%- endset -%}
  {{ include('blocks/section-frame.html.twig', {'p': {'id': v_id, 'title': v_title, 'action': v_action, 'tone': v_tone, 'density': v_density, 'landmarkLabel': v_landmarkLabel}, 'children': c_5}, with_context = false) }}
{%- endif %}
